cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

// Observable contract readings adopted where the specification leaves them open:
// - Rejections ("exits with a non-zero status code", "writes an error description
//   to stderr") are modelled as the scenario runner throwing an Error; the CLI
//   adapter translates a thrown Error into exit code 1 plus a stderr description.
//   The specification establishes no error type or message, so tests require only
//   that an Error is thrown / that the CLI exits non-zero with non-empty stderr.
// - "Alike" components means the same component type (2 runes + 1 moonstone is no
//   block), as fixed by the specification's example.

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest case ---
  it.todo("empty item list -> premium 5 G (processing fee only)");

  // --- Quote: main item base premiums (price-list catalogue, one test per entry) ---
  it.todo("single sword, no modifiers, 0 years, 1st contract -> premium 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("single amulet, no modifiers, 0 years, 1st contract -> premium 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("single staff, no modifiers, 0 years, 1st contract -> premium 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("single potion, no modifiers, 0 years, 1st contract -> premium 49 G (40 base + 4 first insurance + 5 fee)");

  // --- Quote: component base premiums and the building block ---
  it.todo("1 rune -> base premium 25 G");
  it.todo("1 moonstone -> base premium 25 G");
  it.todo("2 runes -> base premium 50 G (no block)");
  it.todo("3 runes -> base premium 60 G (block applies)");
  it.todo("4 runes -> base premium 100 G (no block -- block requires exactly 3)");
  it.todo("7 runes -> base premium 175 G (no block -- block requires exactly 3)");
  it.todo("2 runes + 1 moonstone -> base premium 75 G (no block: different types)");
  it.todo("3 runes + 3 moonstones -> base premium 120 G (two separate blocks)");

  // --- Quote: item-specific modifiers ---
  it.todo("cursed sword adds a 50 % surcharge on that item's base premium -> 50 G added");
  it.todo("sword with enchantment 5 adds a 30 % high-enchantment surcharge -> 30 G added (threshold is inclusive)");
  it.todo("sword with enchantment 4 adds no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 adds both surcharges -> 50 G + 30 G added");

  // --- Quote: policy-wide modifiers ---
  it.todo("customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
  it.todo("customer with 1 year with MHPCO receives no loyalty discount");
  it.todo("every quote carries the 10 % first-insurance surcharge on the policy base premium");
  it.todo("the second quote in a scenario receives the 15 % follow-up-contract discount");
  it.todo("the first quote in a scenario receives no follow-up-contract discount");
  it.todo("the 5 G processing fee is added at the very end, after all modifiers");

  // --- Quote: modifier scope on multi-item policies ---
  it.todo("cursed sword (100 G) + plain amulet (60 G) -> policy base 160 G, curse adds 50 G (of the sword only) -> 210 G before policy-wide modifiers and fee");

  // --- Quote: rounding in MHPCO's favour ---
  it.todo("a premium calculation yielding 197.5 G -> final premium 198 G (rounded up)");
  it.todo("intermediate premium amounts are kept as fractions; only the final premium is rounded");

  // --- Quote: integration examples ---
  it.todo("newcomer (0 years) with a cursed steel sword enchantment 3 -> premium 165 G");
  it.todo("3-year customer's second quote, cursed steel sword enchantment 7 -> premium 160 G");

  // --- Quote: rejection ---
  it.todo("quote with an unknown item type (broomstick) -> throws an Error; CLI exits non-zero with a stderr description and no results on stdout");

  // --- Claim: insurance sum and cap ---
  it.todo("policy covering a sword -> insurance sum 1000 G, cap 2000 G");
  it.todo("policy covering a sword and an amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering two swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("policy covering a sword and 3 runes (a block) -> insurance sum 1750 G; the block discount does not change the insurance sum");
  it.todo("cursed sword (premium with modifiers 165 G) -> cap 2000 G, based on the unmodified insurance value");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("steel sword enchantment 3, damage 500 G -> payout 400 G (full reimbursement minus 100 G deductible)");
  it.todo("rune (no enchantment, no material), damage 200 G -> payout 100 G (full reimbursement minus 100 G deductible)");
  it.todo("damage below the deductible -> payout 0 G (payout is never negative)");

  // --- Claim: special clauses ---
  it.todo("steel sword enchantment 9, damage 1000 G -> payout 400 G (50 % clause first, then deductible)");
  it.todo("steel sword enchantment 8, damage 1000 G -> 50 % clause applies at the inclusive threshold");
  it.todo("steel sword enchantment 7, damage 1000 G -> payout 900 G (no 50 % clause)");
  it.todo("dragon-material sword enchantment 5, damage 800 G -> payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword enchantment 9, damage 1000 G -> payout 400 G (50 % rule wins over dragon material)");
  it.todo("dragon-material sword enchantment 8, damage 1000 G -> payout 400 G (high-enchantment clause applies, then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damaging a sword (500 G) and an amulet (300 G) -> payout 600 G (deductible applies once per damaged item)");
  it.todo("two sword damages against a policy covering two swords -> each entry is a separate damage with its own deductible");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("sword policy (cap 2000 G), first claim of 1500 G -> payout 1400 G, remainingCap 600 G");
  it.todo("sword policy, second successive claim of 1500 G -> payout 600 G, remainingCap 0 G (reduced to the remaining cap)");

  // --- Claim: rounding in MHPCO's favour ---
  it.todo("a payout calculation yielding 350.5 G -> final payout 350 G (rounded down)");

  // --- Claim: rejections ---
  it.todo("claim naming an item type not covered by the policy (amulet when only a sword is insured) -> throws an Error; CLI exits non-zero with a stderr description");
  it.todo("claim naming an unknown item type -> throws an Error; CLI exits non-zero with a stderr description");
  it.todo("claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -> throws an Error; CLI exits non-zero with a stderr description");
  it.todo("claim with a damage entry of amount -200 -> throws an Error; CLI exits non-zero with a stderr description");

  // --- CLI adapter ---
  it.todo("CLI reads the schema example scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("CLI emits one result per step: {premium} for quote steps, {payout, remainingCap} for claim steps");
  it.todo("CLI exits with status 0 and writes valid JSON for a successful scenario");
});
EOF
