cat > src/claim-office.ts <<'EOF'
const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
};

export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface ScenarioResults {
  results: unknown[];
}

function quotePremium(items: Item[]): number {
  const policyBasePremium = items.reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
  return policyBasePremium + policyBasePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): ScenarioResults {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
}
EOF
